insert into public.course_content_draft (course_id, what_you_build, what_you_learn, session, starter_code, test_it_out, troubleshooting, resources, tier, change_note)
values (
  20,
  $wyb$A batch processor that reads a folder of CV PDFs, sends each one alongside your job description to the AI for scoring on skills match, experience, culture fit, and growth trajectory, then writes structured results -- score, strengths, gaps, recommendation -- into an Airtable base sorted by score. A consistency guard flags any candidate whose overall_score doesn't actually follow from its four component scores, and an optional blind-review mode redacts common identity signals before scoring.$wyb$,
  $wyl$[
  "Write a rubric-based job description that gives the AI clear, explicit scoring criteria",
  "Parse a structured scoring reply defensively, stripping a code fence the AI wasn't supposed to add",
  "Sanity-check an aggregate score against the components it's meant to summarize, not just trust it",
  "Extract just the fields you need (name, email) from the top of a document to save tokens",
  "Write records to Airtable via its REST API, respecting its rate limit",
  "Build an optional bias-reduction 'blind review' mode with real, tested regex redaction"
]$wyl$::jsonb,
  $sess${
  "model": "Google Gemini (gemini-flash-latest) or Claude Haiku 4.5 - your choice, see sdt_ai.py setup",
  "builds": [
    {
      "time": "30 min",
      "steps": [
        {
          "instruction": "Make an empty folder for this project and open it in your code editor (in VS Code: File > Open Folder). Inside it, create `requirements.txt` with this content - it lists every library this project uses:",
          "prompt": "requests\npython-dotenv\nPyPDF2\n",
          "verify": "requirements.txt sits directly inside your project folder, not in a subfolder. The next step installs everything it lists."
        },
        {
          "instruction": "Set up Python for this project (once, about 5 minutes). Check your version with `python3 --version` on Mac/Linux or `py --version` on Windows. If it is missing or older than 3.10, install the latest Python from python.org/downloads (on Windows, tick \"Add python.exe to PATH\" on the installer's first screen), then open a new terminal. Now open a terminal in your project folder (in VS Code: Terminal > New Terminal) and run the commands below for your system. They create a virtual environment - a private set of libraries for this project only - and install everything requirements.txt lists.",
          "prompt": "# Mac / Linux\npython3 -m venv .venv\nsource .venv/bin/activate\npython -m pip install -r requirements.txt\n\n# Windows (PowerShell)\npy -m venv .venv\n.venv\\Scripts\\Activate.ps1\npython -m pip install -r requirements.txt\n\n# Windows says \"running scripts is disabled\"? Run this once, then the Activate line again:\n#   Set-ExecutionPolicy -Scope CurrentUser RemoteSigned\n# Ubuntu/Debian says venv or ensurepip is not available? Run: sudo apt install python3-venv",
          "verify": "Your terminal prompt now starts with (.venv), and the install ended with \"Successfully installed\". Each time you open a new terminal for this project, run the activate line again first - while it is active, plain `python` works on every system, and that is the command every step below uses."
        },
        {
          "prompt": "\"\"\"\nSocial Dev Technologies - your connection to the AI.\n\nYou have TWO ways to power this file. Pick ONE and set it in your .env:\n\n  AI_PROVIDER=gemini    -> your own FREE Google Gemini API key\n  AI_PROVIDER=claude    -> your own Claude/Anthropic API key\n\nEvery project in this course calls ask_ai(...) the exact same way no\nmatter which one you pick - this file is the only place that changes.\n\nSETUP - OPTION 1: Gemini (free, no billing needed):\n\n  1. Go to https://aistudio.google.com/apikey and sign in with any Google\n     account. Click \"Create API key\" - free, no card required.\n  2. In the same folder as this file, create a file named exactly: .env\n  3. Put these two lines inside it:\n\n         AI_PROVIDER=gemini\n         GEMINI_API_KEY=paste_your_own_key_here\n\nSETUP - OPTION 2: Claude (if you already have a paid Claude account):\n\n  1. Go to https://console.anthropic.com/settings/keys and create an API\n     key. This needs billing set up on your Anthropic account - it is a\n     separate thing from a claude.ai Pro subscription, and is billed by\n     Anthropic based on what you actually use.\n  2. In your .env file, put these two lines instead:\n\n         AI_PROVIDER=claude\n         ANTHROPIC_API_KEY=paste_your_own_key_here\n\nNever share either key or put it on GitHub - each one is billed to YOUR\naccount. That's it. Every project in this course reuses this same file.\n\"\"\"\n\nimport os\nimport time\n\nimport requests\nfrom dotenv import load_dotenv\n\n# Reads the .env file sitting next to your project and loads your keys.\nload_dotenv()\n\n# \"gemini-flash-latest\" is Google's name for whatever its newest Flash model\n# is, so this file keeps working when Google retires an older model - which\n# it does regularly. You can pin one specific model with GEMINI_MODEL=... in\n# your .env, but if you ever get a \"not available\" error, delete that line.\nGEMINI_MODEL = os.environ.get(\"GEMINI_MODEL\", \"gemini-flash-latest\")\nGEMINI_URL_TEMPLATE = \"https://generativelanguage.googleapis.com/v1beta/models/{model}:generateContent\"\n\n# Gemini \"thinks\" before it answers, and that hidden thinking counts toward\n# the same token limit as the answer itself. With a small max_tokens (the\n# 50-300 used for short replies in this course) the thinking could use up\n# the whole limit and the answer would come back empty. So this file turns\n# thinking down to its minimum (these projects don't need it) and gives\n# Gemini this many extra tokens on top of your max_tokens for whatever\n# thinking is left.\nTHINKING_ALLOWANCE = 1024\n\nCLAUDE_MODEL = os.environ.get(\"CLAUDE_MODEL\", \"claude-haiku-4-5\")\nANTHROPIC_URL = \"https://api.anthropic.com/v1/messages\"\nANTHROPIC_VERSION = \"2023-06-01\"\n\n# Both AIs occasionally answer \"overloaded\" during busy periods (Gemini's\n# free tier especially). That's not your code being wrong - retrying a\n# couple of times almost always gets a real answer, so it's built in here\n# rather than left for every project to handle separately.\nMAX_ATTEMPTS = 3\nRETRY_DELAY_SECONDS = 3\n\n\nclass AIError(Exception):\n    \"\"\"Something went wrong talking to the AI. The message explains what.\"\"\"\n\n\ndef _get_provider():\n    \"\"\"\n    Reads AI_PROVIDER from .env. Falls back to guessing from whichever key\n    is actually present, so forgetting to set AI_PROVIDER explicitly\n    doesn't crash a setup that only has one key configured.\n    \"\"\"\n    provider = os.environ.get(\"AI_PROVIDER\", \"\").strip().lower()\n    if provider in (\"gemini\", \"claude\"):\n        return provider\n\n    if os.environ.get(\"GEMINI_API_KEY\"):\n        return \"gemini\"\n    if os.environ.get(\"ANTHROPIC_API_KEY\"):\n        return \"claude\"\n\n    raise AIError(\n        \"No AI provider configured.\\n\"\n        \"Add ONE of these pairs to your .env file:\\n\\n\"\n        \"    AI_PROVIDER=gemini\\n\"\n        \"    GEMINI_API_KEY=paste_your_free_key_here\\n\\n\"\n        \"  ...or...\\n\\n\"\n        \"    AI_PROVIDER=claude\\n\"\n        \"    ANTHROPIC_API_KEY=paste_your_own_key_here\\n\\n\"\n        \"Get a free Gemini key at https://aistudio.google.com/apikey\"\n    )\n\n\ndef _ask_gemini(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"GEMINI_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to gemini but no GEMINI_API_KEY was found.\\n\"\n            \"Get a free key at https://aistudio.google.com/apikey and add \"\n            \"it to .env:\\n\"\n            \"    GEMINI_API_KEY=paste_your_own_key_here\"\n        )\n\n    generation_config = {\"maxOutputTokens\": max_tokens + THINKING_ALLOWANCE}\n    # thinkingBudget 0 = \"as little thinking as possible\". Pro models can't\n    # turn thinking down and reject this setting, so it's left off for them.\n    if \"-pro\" not in GEMINI_MODEL:\n        generation_config[\"thinkingConfig\"] = {\"thinkingBudget\": 0}\n\n    payload = {\n        \"contents\": [{\"role\": \"user\", \"parts\": [{\"text\": prompt}]}],\n        \"generationConfig\": generation_config,\n    }\n    if system:\n        payload[\"systemInstruction\"] = {\"parts\": [{\"text\": system}]}\n\n    url = GEMINI_URL_TEMPLATE.format(model=GEMINI_MODEL)\n    # The key goes in a header rather than the URL, so it never shows up in\n    # an error message or traceback you might paste somewhere for help.\n    headers = {\"x-goog-api-key\": api_key}\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(url, headers=headers, json=payload, timeout=90)\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Gemini. Check your internet connection and try again.\"\n            ) from None\n\n        if response.status_code in (500, 503):\n            last_problem = f\"Gemini is busy ({response.status_code} - high demand on the free tier)\"\n            if attempt < MAX_ATTEMPTS - 1:\n                time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        if response.status_code == 429:\n            raise AIError(\n                \"Gemini says you've hit the free tier's rate limit. Wait a \"\n                \"minute and try again - the free tier only allows a \"\n                \"limited number of requests per minute.\"\n            )\n\n        if response.status_code == 404:\n            if os.environ.get(\"GEMINI_MODEL\"):\n                advice = (\n                    \"Your .env file sets GEMINI_MODEL - delete that line so this \"\n                    \"file uses its default model, then try again.\"\n                )\n            else:\n                advice = \"Check the course page for an updated copy of sdt_ai.py.\"\n            raise AIError(\n                f'Gemini says the model \"{GEMINI_MODEL}\" isn\\'t available to your '\n                f\"API key - Google retires older models.\\n{advice}\\n\"\n                f\"Details: {response.text[:300]}\"\n            )\n\n        if response.status_code == 400:\n            # If a future Gemini model ever refuses the thinking setting\n            # above, ask again without it instead of failing.\n            if \"thinkingConfig\" in generation_config and \"thinking\" in response.text.lower():\n                del generation_config[\"thinkingConfig\"]\n                last_problem = \"Gemini rejected the thinking setting\"\n                continue\n            raise AIError(\n                f\"Gemini rejected the request - double check your GEMINI_API_KEY \"\n                f\"is correct: {response.text[:300]}\"\n            )\n\n        if response.status_code != 200:\n            raise AIError(\n                f\"Gemini returned an error (status {response.status_code}): {response.text[:300]}\"\n            )\n\n        data = response.json()\n        candidates = data.get(\"candidates\") or []\n        if not candidates:\n            block_reason = (data.get(\"promptFeedback\") or {}).get(\"blockReason\")\n            if block_reason:\n                raise AIError(f\"Gemini refused the prompt ({block_reason}). Try rephrasing it.\")\n            raise AIError(f\"Unexpected reply from Gemini: {data}\")\n        candidate = candidates[0]\n        finish_reason = candidate.get(\"finishReason\")\n\n        # A response can come back with no text because Gemini's safety\n        # filters blocked it (finishReason == \"SAFETY\"), not because of a\n        # network problem - so this is not retried like the cases above.\n        if finish_reason == \"SAFETY\":\n            raise AIError(\"Gemini declined to answer (safety filter). Try rephrasing your prompt.\")\n\n        # An answer can arrive split across several parts, so join them all.\n        # Any part marked \"thought\" is Gemini's thinking, not its answer.\n        parts = (candidate.get(\"content\") or {}).get(\"parts\") or []\n        text = \"\".join(part.get(\"text\", \"\") for part in parts if not part.get(\"thought\"))\n        if not text:\n            if finish_reason == \"MAX_TOKENS\":\n                raise AIError(\n                    \"Gemini ran out of room before it wrote any answer - its thinking \"\n                    f\"used up all {generation_config['maxOutputTokens']} tokens it was \"\n                    \"allowed. Raise max_tokens in this ask_ai(...) call (try \"\n                    f\"max_tokens={max(max_tokens * 2, 4000)}) and run it again.\"\n                )\n            raise AIError(\n                f\"Gemini sent back an empty answer (finishReason: {finish_reason}). \"\n                \"Try again, or rephrase your prompt.\"\n            )\n\n        usage = data.get(\"usageMetadata\") or {}\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"promptTokenCount\"),\n            \"output_tokens\": usage.get(\"candidatesTokenCount\"),\n        }\n\n    raise AIError(\n        f\"Gemini was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"This happens sometimes on the free tier during high demand - wait \"\n        \"a minute and try again.\"\n    )\n\n\ndef _ask_claude(prompt, system=None, max_tokens=1000):\n    api_key = os.environ.get(\"ANTHROPIC_API_KEY\")\n    if not api_key:\n        raise AIError(\n            \"AI_PROVIDER is set to claude but no ANTHROPIC_API_KEY was found.\\n\"\n            \"Create one at https://console.anthropic.com/settings/keys and \"\n            \"add it to .env:\\n\"\n            \"    ANTHROPIC_API_KEY=paste_your_own_key_here\"\n        )\n\n    payload = {\n        \"model\": CLAUDE_MODEL,\n        \"max_tokens\": max_tokens,\n        \"messages\": [{\"role\": \"user\", \"content\": prompt}],\n    }\n    if system:\n        payload[\"system\"] = system\n\n    last_problem = \"no response\"\n    for attempt in range(MAX_ATTEMPTS):\n        try:\n            response = requests.post(\n                ANTHROPIC_URL,\n                headers={\n                    \"x-api-key\": api_key,\n                    \"anthropic-version\": ANTHROPIC_VERSION,\n                    \"Content-Type\": \"application/json\",\n                },\n                json=payload,\n                timeout=90,\n            )\n        except requests.RequestException:\n            raise AIError(\n                \"Could not reach Claude. Check your internet connection and try again.\"\n            ) from None\n\n        # 529 is Anthropic's \"overloaded\" - like Gemini's 503, a retry\n        # usually works.\n        if response.status_code in (500, 503, 529):\n            last_problem = f\"Claude is busy ({response.status_code} - overloaded)\"\n            if attempt < MAX_ATTEMPTS - 1:\n                time.sleep(RETRY_DELAY_SECONDS)\n            continue\n\n        try:\n            data = response.json()\n        except ValueError:\n            raise AIError(f\"Unexpected reply from Claude (status {response.status_code}).\") from None\n\n        if response.status_code == 401:\n            raise AIError(\n                \"Claude rejected your ANTHROPIC_API_KEY - double check it was copied correctly.\"\n            )\n\n        if response.status_code == 429:\n            raise AIError(\"Claude says you've hit your rate or usage limit. Wait a moment and try again.\")\n\n        if response.status_code == 404:\n            if os.environ.get(\"CLAUDE_MODEL\"):\n                advice = (\n                    \"Your .env file sets CLAUDE_MODEL - delete that line so this \"\n                    \"file uses its default model, then try again.\"\n                )\n            else:\n                advice = \"Check the course page for an updated copy of sdt_ai.py.\"\n            raise AIError(\n                f'Claude says the model \"{CLAUDE_MODEL}\" isn\\'t available to your '\n                f\"API key.\\n{advice}\"\n            )\n\n        if \"error\" in data or response.status_code != 200:\n            error = data.get(\"error\") or {}\n            message = error.get(\"message\") if isinstance(error, dict) else str(error)\n            raise AIError(\n                f\"Claude returned an error (status {response.status_code}): \"\n                f\"{message or str(data)[:300]}\"\n            )\n\n        text = \"\".join(\n            block.get(\"text\", \"\") for block in data.get(\"content\", []) if block.get(\"type\") == \"text\"\n        )\n        if not text:\n            raise AIError(\n                f\"Claude sent back an empty answer (stop_reason: {data.get('stop_reason')}). \"\n                \"Try again, or rephrase your prompt.\"\n            )\n\n        usage = data.get(\"usage\") or {}\n        return {\n            \"text\": text,\n            \"input_tokens\": usage.get(\"input_tokens\"),\n            \"output_tokens\": usage.get(\"output_tokens\"),\n        }\n\n    raise AIError(\n        f\"Claude was unavailable after {MAX_ATTEMPTS} tries ({last_problem}). \"\n        \"Wait a minute and try again.\"\n    )\n\n\ndef ask_ai_detailed(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Same as ask_ai, but returns the whole reply as a dict.\n\n        result = ask_ai_detailed(\"Summarise this\", max_tokens=200)\n        print(result[\"text\"])\n    \"\"\"\n    provider = _get_provider()\n    if provider == \"gemini\":\n        return _ask_gemini(prompt, system=system, max_tokens=max_tokens)\n    return _ask_claude(prompt, system=system, max_tokens=max_tokens)\n\n\ndef ask_ai(prompt, system=None, max_tokens=1000, project=None):\n    \"\"\"\n    Send a question to the AI and get the answer back as text.\n\n        answer = ask_ai(\"Write a haiku about Lagos traffic\")\n        print(answer)\n\n    prompt      - what you want the AI to do. This is the important part.\n    system      - optional. Sets the AI's role, e.g. \"You are a careful editor.\"\n    max_tokens  - roughly how long the answer may be. 1000 is plenty for most.\n    project     - unused, kept so call sites read the same across every\n                  project regardless of which AI is behind this file.\n\n    Works identically whichever provider your .env is set to - every\n    project in this course calls this one function and never needs to\n    know which AI is actually answering.\n\n    Returns the AI's answer as a plain string.\n    Raises AIError with a readable message if something is wrong.\n    \"\"\"\n    return ask_ai_detailed(prompt, system=system, max_tokens=max_tokens, project=project)[\"text\"]\n\n\nif __name__ == \"__main__\":\n    # Running this file directly checks that your setup works.\n    print(\"Testing your AI connection...\\n\")\n    try:\n        provider = _get_provider()\n        model = GEMINI_MODEL if provider == \"gemini\" else CLAUDE_MODEL\n        result = ask_ai_detailed(\"Say hello in exactly five words.\", max_tokens=50)\n        print(f\"Provider: {provider} ({model})\")\n        print(\"The AI said:\", result[\"text\"])\n        print(\"\\nYour setup works. You are ready to build.\")\n    except AIError as problem:\n        print(\"Setup problem:\\n\")\n        print(problem)\n",
          "verify": "Don't run it yet - it needs the .env file from the next step first.",
          "instruction": "Create `sdt_ai.py` in your project folder with this code. You'll reuse this exact file, unmodified, in every future project in this course:"
        },
        {
          "prompt": "# OPTION 1: your own free Gemini key (recommended - no billing needed)\n# Get one free at https://aistudio.google.com/apikey - no credit card needed\nAI_PROVIDER=gemini\nGEMINI_API_KEY=paste_your_own_key_here\n\n# OPTION 2: your own Claude/Anthropic key (comment OPTION 1 out above,\n# uncomment these two lines instead - needs billing set up on your own\n# Anthropic account)\n# Get one at https://console.anthropic.com/settings/keys\n# AI_PROVIDER=claude\n# ANTHROPIC_API_KEY=paste_your_own_key_here\n\n# Airtable - the Base ID is the part of your base's URL that starts with\n# \"app\". AIRTABLE_API_KEY is a personal access token: create one at\n# airtable.com/create/tokens with the data.records:write scope and\n# access to this base (Airtable retired plain API keys in 2024)\nAIRTABLE_BASE_ID=paste_your_base_id_here\nAIRTABLE_API_KEY=paste_your_personal_access_token_here\n",
          "verify": "Run `python sdt_ai.py` - it should print which provider you're using, then `The AI said: ...`, and end with `Your setup works. You are ready to build.` If you see `No AI provider configured` instead, check that .env sits next to sdt_ai.py and that AI_PROVIDER plus its matching key are both uncommented.",
          "instruction": "Create `.env` in the same folder with ONE of the two setups below — pick whichever you're using, then replace the placeholder with your real key:"
        },
        {
          "verify": "Show your jd.txt to a colleague and ask if they'd score a hypothetical candidate the same way - if your red flags are too vague, sharpen them now.",
          "instruction": "Create `jd.txt` with: Role title, Required skills/experience, Nice-to-haves, and an explicit \"Red flags\" section (e.g. \"no evidence of production ownership\", \"frequent <1yr job hops without explanation\"). Red flags matter - without them, scores tend to cluster too high."
        },
        {
          "verify": "Confirm your Candidates table has all 6 fields with the right types - Score must be a number field for sorting to work correctly later.",
          "instruction": "In Airtable, create a base with a \"Candidates\" table containing fields: Name (text), Email (text), Score (number), Strengths (long text), Gaps (long text), Recommendation (single select: Strong Yes/Yes/Maybe/No). Create a view sorted by Score descending."
        },
        {
          "verify": "Open each PDF and confirm the text is actually selectable/searchable (not a scanned image) - a scanned CV has no embedded text for PyPDF2 to extract.",
          "instruction": "Put 3-5 sample CV PDFs into a `cvs/` folder."
        }
      ],
      "title": "Write your JD rubric and set up Airtable",
      "number": 1,
      "goFurther": "Deliberately write jd.txt for a role very different from any of your sample CVs, and note your own prediction of how each candidate should score - you'll compare this to the AI's actual scores in Build 2.",
      "description": "The scoring is only as good as the rubric you give the AI."
    },
    {
      "time": "45 min",
      "steps": [
        {
          "prompt": "\"\"\"\nStep 2 of the HR Recruitment Screening Agent (part 1) - extracts text\nfrom every CV PDF in a folder.\n\"\"\"\n\nimport os\n\nfrom PyPDF2 import PdfReader\n\n\ndef read_cvs(folder=\"cvs\"):\n    \"\"\"\n    Reads every .pdf file in folder and returns {path: extracted_text}.\n\n        cvs = read_cvs(\"cvs\")\n\n    Skips any file that isn't a .pdf, and skips (with a printed warning,\n    not a crash) any PDF that fails to extract at all - a single\n    corrupted file in a folder of 20 CVs shouldn't stop the other 19\n    from being screened.\n    \"\"\"\n    texts = {}\n    for filename in sorted(os.listdir(folder)):\n        if not filename.lower().endswith(\".pdf\"):\n            continue\n        path = os.path.join(folder, filename)\n        try:\n            reader = PdfReader(path)\n            texts[path] = \"\\n\".join(page.extract_text() or \"\" for page in reader.pages)\n        except Exception as problem:\n            print(f\"Skipped {filename}: could not read as a PDF ({problem})\")\n    return texts\n\n\nif __name__ == \"__main__\":\n    print(\"This file only wraps real PDF reads from disk - there's no\")\n    print(\"offline self-test here. It's exercised for real in Build 3's batch.py,\")\n    print(\"once you have real CV PDFs in your cvs/ folder.\")\n",
          "verify": "This file only wraps real PDF reads - there's no offline self-test to run here.",
          "instruction": "Create `cv_reader.py` with this code:"
        },
        {
          "prompt": "\"\"\"\nStep 2 of the HR Recruitment Screening Agent (part 2).\n\nTurns a CV and a job description into a structured, 1-10 score across\nfour dimensions. The JSON parsing is defensive (a stray code fence is\nstripped, not fatal), and this project's safety guard checks that\noverall_score is actually consistent with the four dimension scores\nit's supposed to summarize - not just any number 1-10 the AI feels like.\n\"\"\"\n\nimport json\n\nfrom sdt_ai import ask_ai\n\nSCORE_FIELDS = [\"skills_match\", \"experience_level\", \"culture_fit\", \"growth_trajectory\", \"overall_score\"]\nVALID_RECOMMENDATIONS = {\"Strong Yes\", \"Yes\", \"Maybe\", \"No\"}\n\n# How far overall_score is allowed to drift from the average of the 4\n# dimension scores before this project flags it for manual review. A\n# real LLM failure mode: it reasons carefully about each dimension, then\n# writes an overall_score that doesn't actually follow from them (e.g.\n# all four dimensions score 4-5, but overall_score comes back as 9).\nMAX_OVERALL_SCORE_DRIFT = 3\n\nMAX_CV_CHARACTERS = 6000\n\n\ndef build_prompt(cv_text, jd_text):\n    trimmed = cv_text[:MAX_CV_CHARACTERS]\n    return f\"\"\"Job description:\n{jd_text}\n\nCandidate CV:\n{trimmed}\n\nScore the candidate 1-10 on each of: skills_match, experience_level,\nculture_fit, growth_trajectory. Then give an overall_score (1-10) that\nshould be roughly consistent with those four - not a separate,\nunrelated judgment.\n\nAlso give top 3 strengths, top 2 gaps (as arrays of strings), and a\nrecommendation - exactly one of: \"Strong Yes\", \"Yes\", \"Maybe\", \"No\".\n\nReturn ONLY this JSON shape, no markdown code fence, no explanation:\n{{\"skills_match\": 0, \"experience_level\": 0, \"culture_fit\": 0, \"growth_trajectory\": 0,\n\"overall_score\": 0, \"strengths\": [\"...\", \"...\", \"...\"], \"gaps\": [\"...\", \"...\"],\n\"recommendation\": \"...\"}}\"\"\"\n\n\ndef parse_score_reply(reply):\n    \"\"\"\n    Turns the AI's reply into a dict, tolerating a ```json code fence.\n    Returns None (never raises) if the reply isn't valid JSON at all.\n    \"\"\"\n    cleaned = reply.strip()\n    if cleaned.startswith(\"```\"):\n        lines = cleaned.splitlines()[1:]\n        if lines and lines[-1].strip() == \"```\":\n            lines = lines[:-1]\n        cleaned = \"\\n\".join(lines)\n\n    try:\n        return json.loads(cleaned)\n    except json.JSONDecodeError:\n        return None\n\n\ndef validate_score(data):\n    \"\"\"\n    Checks the parsed score data for two things: every required field\n    is present and numerically in range, and overall_score is actually\n    consistent with the four dimension scores it's meant to summarize.\n\n    Mutates and returns data with an extra \"needs_review\" field (and a\n    \"review_reason\" if True) - this NEVER changes overall_score itself,\n    it only flags a suspicious one for a human to double check, the same\n    \"flag, don't silently fix\" pattern used throughout this course.\n    \"\"\"\n    missing = [f for f in SCORE_FIELDS if not isinstance(data.get(f), (int, float))]\n    if missing:\n        data[\"needs_review\"] = True\n        data[\"review_reason\"] = f\"Missing or non-numeric field(s): {', '.join(missing)}\"\n        return data\n\n    out_of_range = [f for f in SCORE_FIELDS if not (1 <= data[f] <= 10)]\n    if out_of_range:\n        data[\"needs_review\"] = True\n        data[\"review_reason\"] = f\"Field(s) outside the 1-10 range: {', '.join(out_of_range)}\"\n        return data\n\n    dimension_scores = [data[f] for f in SCORE_FIELDS if f != \"overall_score\"]\n    average = sum(dimension_scores) / len(dimension_scores)\n    drift = abs(data[\"overall_score\"] - average)\n\n    if drift > MAX_OVERALL_SCORE_DRIFT:\n        data[\"needs_review\"] = True\n        data[\"review_reason\"] = (\n            f\"overall_score ({data['overall_score']}) is {drift:.1f} points away from \"\n            f\"the average of the four dimension scores ({average:.1f}) - check whether \"\n            f\"either number actually reflects the CV.\"\n        )\n        return data\n\n    if data.get(\"recommendation\") not in VALID_RECOMMENDATIONS:\n        data[\"needs_review\"] = True\n        data[\"review_reason\"] = f\"Unrecognised recommendation: {data.get('recommendation')!r}\"\n        return data\n\n    data[\"needs_review\"] = False\n    data[\"review_reason\"] = \"\"\n    return data\n\n\ndef score_candidate(cv_text, jd_text):\n    \"\"\"\n    The main function. Give it CV text and a job description, get back\n    the validated score dict.\n    \"\"\"\n    prompt = build_prompt(cv_text, jd_text)\n    reply = ask_ai(prompt, max_tokens=600, project=\"hr-recruitment-screening-agent\")\n\n    data = parse_score_reply(reply)\n    if data is None:\n        raise ValueError(\n            \"The AI's reply wasn't valid JSON.\\n\"\n            \"Run it again - this usually fixes itself.\\n\"\n            \"If it keeps happening, print(reply) to see what came back.\"\n        )\n\n    return validate_score(data)\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check parsing and the consistency\n    # guard work - no AI call, no API usage:  python score.py\n\n    print(\"Checking a well-formed, internally consistent score...\")\n    good = {\n        \"skills_match\": 8, \"experience_level\": 7, \"culture_fit\": 7, \"growth_trajectory\": 8,\n        \"overall_score\": 7, \"strengths\": [\"a\", \"b\", \"c\"], \"gaps\": [\"x\", \"y\"],\n        \"recommendation\": \"Yes\",\n    }\n    result = validate_score(dict(good))\n    assert result[\"needs_review\"] is False\n    print(\"  OK - needs_review is False\")\n\n    print(\"\\nChecking a score where overall_score doesn't match the dimensions at all...\")\n    inconsistent = dict(good)\n    inconsistent[\"overall_score\"] = 2\n    result = validate_score(inconsistent)\n    assert result[\"needs_review\"] is True\n    assert \"overall_score\" in result[\"review_reason\"]\n    print(\"  OK -\", result[\"review_reason\"])\n\n    print(\"\\nChecking a score with a field out of the 1-10 range...\")\n    out_of_range = dict(good)\n    out_of_range[\"skills_match\"] = 15\n    result = validate_score(out_of_range)\n    assert result[\"needs_review\"] is True\n    assert \"skills_match\" in result[\"review_reason\"]\n    print(\"  OK -\", result[\"review_reason\"])\n\n    print(\"\\nChecking a score with a missing field entirely...\")\n    missing_field = dict(good)\n    del missing_field[\"culture_fit\"]\n    result = validate_score(missing_field)\n    assert result[\"needs_review\"] is True\n    assert \"culture_fit\" in result[\"review_reason\"]\n    print(\"  OK -\", result[\"review_reason\"])\n\n    print(\"\\nChecking an unrecognised recommendation string...\")\n    bad_recommendation = dict(good)\n    bad_recommendation[\"recommendation\"] = \"Definitely hire!!\"\n    result = validate_score(bad_recommendation)\n    assert result[\"needs_review\"] is True\n    print(\"  OK -\", result[\"review_reason\"])\n\n    print(\"\\nChecking parse_score_reply() strips a ```json code fence...\")\n    fenced = '```json\\n{\"overall_score\": 7}\\n```'\n    assert parse_score_reply(fenced) == {\"overall_score\": 7}\n    print(\"  OK\")\n\n    print(\"\\nChecking a non-JSON reply returns None instead of crashing...\")\n    assert parse_score_reply(\"Sorry, I can't score that.\") is None\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python score.py` (no AI call, no API usage - this only tests parsing and the consistency guard against fake data). You should see a consistent score correctly pass, an overall_score wildly out of line with its dimensions correctly flagged, an out-of-range field correctly flagged, a missing field correctly flagged, an unrecognised recommendation correctly flagged, a ```json fence correctly stripped, and a non-JSON reply correctly returning None - ending with `All checks passed.`",
          "instruction": "Create `score.py` with this code:"
        },
        {
          "prompt": "python -c \"from cv_reader import read_cvs; from score import score_candidate; cvs = read_cvs(); path, text = next(iter(cvs.items())); import json; print(json.dumps(score_candidate(text, open('jd.txt').read()), indent=2))\"",
          "verify": "You should get back a JSON object with all the scoring fields filled in with sensible values, and the strengths/gaps should reference things actually in that CV, not generic statements. needs_review should be False for a normal, consistent score.",
          "instruction": "Now score one real CV against your jd.txt:"
        },
        {
          "prompt": "\"\"\"\nStep 2 of the HR Recruitment Screening Agent (part 3) - pulls just the\ncandidate's name and email from the top of their CV, using far fewer\ntokens than sending the whole document.\n\"\"\"\n\nimport json\n\nfrom sdt_ai import ask_ai\n\n# Only the first N characters go into this call. A MONEY decision: a\n# name and email address appear in the first few lines of virtually\n# every CV ever formatted - sending the whole multi-page document to\n# extract two short fields would be paying for content this call never\n# needs to read.\nMAX_HEADER_CHARACTERS = 1000\n\n\ndef build_prompt(cv_text):\n    header = cv_text[:MAX_HEADER_CHARACTERS]\n    return f\"\"\"Extract the candidate's full name and email address from this CV\nexcerpt. Return ONLY this JSON shape, no markdown code fence:\n{{\"name\": \"...\", \"email\": \"...\"}}\n\nIf either isn't findable in this excerpt, use an empty string \"\" - do\nnot guess a plausible-looking name or email.\n\nCV EXCERPT:\n{header}\"\"\"\n\n\ndef parse_contact_reply(reply):\n    \"\"\"Same defensive JSON parsing as score.py - tolerates a code fence, returns None on real garbage.\"\"\"\n    cleaned = reply.strip()\n    if cleaned.startswith(\"```\"):\n        lines = cleaned.splitlines()[1:]\n        if lines and lines[-1].strip() == \"```\":\n            lines = lines[:-1]\n        cleaned = \"\\n\".join(lines)\n\n    try:\n        data = json.loads(cleaned)\n    except json.JSONDecodeError:\n        return None\n    return {\"name\": data.get(\"name\", \"\"), \"email\": data.get(\"email\", \"\")}\n\n\ndef extract_contact(cv_text):\n    \"\"\"The main function. Give it CV text, get back {\"name\": \"...\", \"email\": \"...\"}.\"\"\"\n    prompt = build_prompt(cv_text)\n    reply = ask_ai(prompt, max_tokens=100, project=\"hr-recruitment-screening-agent\")\n\n    contact = parse_contact_reply(reply)\n    if contact is None:\n        raise ValueError(\n            \"The AI's reply wasn't valid JSON.\\n\"\n            \"Run it again - this usually fixes itself.\"\n        )\n    return contact\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check the parsing works - no AI call,\n    # no API usage:  python extract_contact.py\n    print(\"Checking a clean reply...\")\n    clean = '{\"name\": \"Amaka Obi\", \"email\": \"amaka@example.com\"}'\n    assert parse_contact_reply(clean) == {\"name\": \"Amaka Obi\", \"email\": \"amaka@example.com\"}\n    print(\"  OK\")\n\n    print(\"\\nChecking a ```json-fenced reply...\")\n    fenced = '```json\\n{\"name\": \"Chidi Eze\", \"email\": \"\"}\\n```'\n    assert parse_contact_reply(fenced) == {\"name\": \"Chidi Eze\", \"email\": \"\"}\n    print(\"  OK - empty email correctly preserved as '', not dropped\")\n\n    print(\"\\nChecking a non-JSON reply returns None...\")\n    assert parse_contact_reply(\"I couldn't find that information.\") is None\n    print(\"  OK\")\n\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python extract_contact.py`. You should see a clean reply parsed correctly, an empty email correctly preserved as '' rather than dropped, and a non-JSON reply correctly returning None - ending with `All checks passed.`",
          "instruction": "Create `extract_contact.py` with this code:"
        }
      ],
      "title": "Extract CVs and build the scorer",
      "number": 2,
      "goFurther": "🛠️ Run score_candidate() on a CV that's a poor fit for your jd.txt (or write a quick fake one) - confirm the overall_score is meaningfully lower, needs_review is False (a low but CONSISTENT score isn't a review flag), and the gaps section calls out the actual mismatch.",
      "description": "This is the core: turning a CV and a job description into a structured score. The safety guard here checks that the overall_score actually follows from the four dimension scores it's supposed to summarize, instead of trusting it blindly."
    },
    {
      "time": "30 min",
      "steps": [
        {
          "prompt": "\"\"\"\nStep 3 of the HR Recruitment Screening Agent - pushes scored candidates\ninto an Airtable base.\n\"\"\"\n\nimport time\n\nimport requests\n\nAIRTABLE_RATE_LIMIT_DELAY = 0.25  # stays comfortably under Airtable's 5 req/sec limit\n\n\ndef build_record(name, email, score_data):\n    \"\"\"\n    Turns contact info and a validated score dict into the exact field\n    shape your Airtable \"Candidates\" table expects.\n\n        build_record(\"Amaka Obi\", \"amaka@example.com\", score_data)\n\n    Pure function, no network call - tested below without a real base.\n    \"\"\"\n    return {\n        \"Name\": name,\n        \"Email\": email,\n        \"Score\": score_data[\"overall_score\"],\n        \"Strengths\": \"\\n\".join(score_data.get(\"strengths\", [])),\n        \"Gaps\": \"\\n\".join(score_data.get(\"gaps\", [])),\n        \"Recommendation\": score_data.get(\"recommendation\", \"\"),\n    }\n\n\ndef push_to_airtable(base_id, table, api_key, record):\n    \"\"\"POSTs one record to the Airtable REST API.\"\"\"\n    response = requests.post(\n        f\"https://api.airtable.com/v0/{base_id}/{table}\",\n        headers={\"Authorization\": f\"Bearer {api_key}\", \"Content-Type\": \"application/json\"},\n        json={\"fields\": record},\n    )\n    response.raise_for_status()\n    time.sleep(AIRTABLE_RATE_LIMIT_DELAY)\n    return response.json()\n\n\nif __name__ == \"__main__\":\n    # Run this file on its own to check record-building works - no\n    # Airtable account or network call needed:  python airtable_write.py\n    score_data = {\n        \"overall_score\": 8,\n        \"strengths\": [\"Strong Python skills\", \"Led a team of 5\", \"Clear communicator\"],\n        \"gaps\": [\"Limited cloud experience\"],\n        \"recommendation\": \"Yes\",\n    }\n    record = build_record(\"Amaka Obi\", \"amaka@example.com\", score_data)\n    assert record[\"Score\"] == 8\n    assert record[\"Strengths\"] == \"Strong Python skills\\nLed a team of 5\\nClear communicator\"\n    assert record[\"Recommendation\"] == \"Yes\"\n    print(\"Built record:\", record)\n    print(\"\\nAll checks passed.\")\n",
          "verify": "Run `python airtable_write.py` (no Airtable account needed - this only tests record-building). You should see a record built with the score, strengths, and recommendation in the exact shape your Airtable table expects, ending with `All checks passed.`",
          "instruction": "Create `airtable_write.py` with this code:"
        },
        {
          "prompt": "\"\"\"\nStep 3 of the HR Recruitment Screening Agent (continued) - the command\nyou actually run: score every CV in a folder and push ranked results\ninto Airtable.\n\nRun it with:      python batch.py\nBlind mode:       python batch.py --blind\n\"\"\"\n\nimport os\nimport sys\n\nfrom airtable_write import build_record, push_to_airtable\nfrom blind_review import redact_pii\nfrom cv_reader import read_cvs\nfrom dotenv import load_dotenv\nfrom extract_contact import extract_contact\nfrom score import score_candidate\nfrom sdt_ai import AIError\n\nload_dotenv()\n\n\ndef process_all(folder=\"cvs\", blind=False):\n    with open(\"jd.txt\", encoding=\"utf-8\") as f:\n        jd_text = f.read()\n\n    cvs = read_cvs(folder)\n    if not cvs:\n        raise ValueError(f\"No PDF files found in '{folder}/' - add your CVs there first.\")\n\n    base_id = os.environ[\"AIRTABLE_BASE_ID\"]\n    api_key = os.environ[\"AIRTABLE_API_KEY\"]\n\n    for path, cv_text in cvs.items():\n        try:\n            # Contact info always uses the UNREDACTED text - a name and\n            # email are needed either way, and redacting them would just\n            # make the candidate impossible to follow up with.\n            contact = extract_contact(cv_text)\n            scoring_text = redact_pii(cv_text) if blind else cv_text\n            score_data = score_candidate(scoring_text, jd_text)\n        except (AIError, ValueError) as problem:\n            print(f\"Skipped {path}: {problem}\")\n            continue\n\n        record = build_record(contact[\"name\"] or \"(name not found)\", contact[\"email\"], score_data)\n        push_to_airtable(base_id, \"Candidates\", api_key, record)\n\n        flag = \" [NEEDS REVIEW]\" if score_data.get(\"needs_review\") else \"\"\n        print(f\"Processed {record['Name']}: {record['Score']}/10{flag}\")\n\n\nif __name__ == \"__main__\":\n    blind_mode = \"--blind\" in sys.argv\n    process_all(blind=blind_mode)\n",
          "verify": "Run `python batch.py`. Check Airtable - you should see one row per CV, with the Score-sorted view showing your best-fit candidates at the top, and Strengths/Gaps filled in with real text. Any candidate flagged [NEEDS REVIEW] in the console is worth opening by hand before trusting its score.",
          "instruction": "Create `batch.py` with this code, then run it on your real CVs:"
